@layer moduix.components {
  .trigger {
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: var(--moduix-size-md);
    margin: 0;
    padding: var(--moduix-spacing-1) var(--moduix-spacing-3-5);
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-md);
    background-color: var(--moduix-color-background);
    color: var(--moduix-color-foreground);
    font: inherit;
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
    user-select: none;
    outline: 0;
    cursor: pointer;
    transition:
      background-color var(--moduix-transition-default),
      border-color var(--moduix-transition-default),
      color var(--moduix-transition-default);

    @media (hover: hover) {
      &:hover {
        background-color: var(--moduix-color-accent);
      }
    }

    &:active,
    &[data-state='open']:not([data-value]),
    &[data-state='open'][data-current] {
      background-color: var(--moduix-color-accent);
    }

    &:focus-visible {
      outline: var(--moduix-focus-ring-inset-width) solid var(--moduix-color-ring);
      outline-offset: var(--moduix-focus-ring-inset-offset);
    }

    &:disabled {
      pointer-events: none;
      opacity: var(--moduix-opacity-disabled);
    }
  }

  .disabledTrigger {
    display: inline-flex;
    cursor: not-allowed;

    & > :is(:disabled, [data-disabled]) {
      pointer-events: none;
    }
  }

  .positioner {
    z-index: var(--z-index, var(--moduix-z-popup));
    max-width: var(--available-width);
    outline: 0;
  }

  .content {
    position: relative;
    box-sizing: border-box;
    max-width: min(20rem, var(--available-width));
    overflow-wrap: anywhere;
    padding: var(--moduix-spacing-1) var(--moduix-spacing-2);
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-md);
    background-color: var(--moduix-color-popover);
    color: var(--moduix-color-popover-foreground);
    box-shadow: var(--moduix-shadow-md);
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
    text-align: center;
    transform-origin: var(--transform-origin);

    &[data-state='open'] {
      animation: global(moduix-popup-in)
        var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
        var(--moduix-popup-motion-easing, var(--moduix-ease-in-out));
    }

    &[data-state='closed'] {
      animation: global(moduix-popup-out)
        var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
        var(--moduix-popup-motion-easing, var(--moduix-ease-in-out)) forwards;
    }

    /* Ark marks a tooltip that replaces another one while the pointer moves between triggers. */
    &[data-instant] {
      animation: none;
    }
  }

  .arrow {
    --arrow-size: var(--moduix-spacing-2-5);
    --arrow-background: var(--moduix-color-popover);
  }

  .arrowTip {
    border-top: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-left: var(--moduix-border-width-sm) solid var(--moduix-color-border);
  }

  @media (prefers-reduced-motion: reduce) {
    .trigger {
      transition: none;
    }

    .content[data-state] {
      animation: none;
    }
  }
}

import { TooltipContext, useTooltip, useTooltipContext } from '@ark-ui/vue/tooltip';
import Tooltip from './Tooltip.vue';
import TooltipArrow from './TooltipArrow.vue';
import TooltipArrowTip from './TooltipArrowTip.vue';
import TooltipBody from './TooltipBody.vue';
import TooltipContent from './TooltipContent.vue';
import TooltipDisabledTrigger from './TooltipDisabledTrigger.vue';
import TooltipPositioner from './TooltipPositioner.vue';
import TooltipRootProvider from './TooltipRootProvider.vue';
import TooltipTrigger from './TooltipTrigger.vue';

export {
  Tooltip,
  TooltipArrow,
  TooltipArrowTip,
  TooltipBody,
  TooltipContext,
  TooltipContent,
  TooltipDisabledTrigger,
  TooltipPositioner,
  TooltipRootProvider,
  TooltipTrigger,
  useTooltip,
  useTooltipContext,
};

export type {
  TooltipArrowProps,
  TooltipArrowTipProps,
  TooltipContentProps,
  TooltipContextProps,
  TooltipOpenChangeDetails,
  TooltipPositionerProps,
  TooltipRootEmits,
  TooltipRootProviderEmits,
  TooltipTriggerProps,
  TooltipTriggerValueChangeDetails,
  UseTooltipContext,
  UseTooltipProps,
  UseTooltipReturn,
} from '@ark-ui/vue/tooltip';

export type { Props as TooltipRootProps } from './Tooltip.vue';
export type { Props as TooltipRootProviderProps } from './TooltipRootProvider.vue';
